from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    stable = set()
    speckles = []

    # Treat tiny 4-connected components as stray marks.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(comp) <= 2 and color != bg:
                speckles.extend(comp)
            else:
                stable.update(comp)

    totals = Counter(v for row in grid for v in row)
    out = [row[:] for row in grid]

    for r, c in speckles:
        best_dist = h + w
        choices = []
        for y, x in stable:
            d = abs(y - r) + abs(x - c)
            if d < best_dist:
                best_dist = d
                choices = [grid[y][x]]
            elif d == best_dist:
                choices.append(grid[y][x])
        if choices:
            counts = Counter(choices)
            out[r][c] = min(
                counts,
                key=lambda color: (color == bg, -counts[color], -totals[color], color)
            )
        else:
            out[r][c] = bg

    return out
